/**
 * Kitchen Locality Hub Registry — Batch 2a
 * 25 locality hub pages: /modular-kitchen-{locality-slug}
 * One page per locality; all layouts + materials link from it.
 */

import { KITCHEN_LAYOUT_LOCALITY_REGISTRY } from "./kitchen-layout-locality-registry.ts";

export type KitchenLocalityHubEntry = {
  urlSlug: string;          // e.g. "modular-kitchen-greater-kailash"
  localitySlug: string;     // e.g. "greater-kailash"
  localityName: string;
  citySlug: "delhi" | "gurgaon" | "noida" | "faridabad" | "ghaziabad" | "chandigarh" | "mohali" | "panchkula";
  cityName: string;
  affluence: "ultra-high" | "high" | "mid-high" | "mid";
  priceMin: number;
  priceMax: number;
  nearby: string[];         // locality slugs used in Batch 1
};

// ─── Shared FAQ template (parameterised at render time) ─────────────────────
export function buildHubFaqs(e: KitchenLocalityHubEntry) {
  const { localityName, cityName, priceMin, priceMax } = e;
  const fmt = (n: number) =>
    n >= 100000 ? `₹${(n / 100000).toFixed(1).replace(".0", "")}L` : `₹${(n / 1000).toFixed(0)}K`;
  return [
    {
      q: `How much does a modular kitchen cost in ${localityName}?`,
      a: `Modular kitchen prices in ${localityName} range from ${fmt(priceMin)} to ${fmt(priceMax)} depending on the layout, finish, and hardware brand. Laminate kitchens start at the lower end; premium acrylic or PU finishes with imported hardware are at the higher end. FurniRevive offers a free home visit and transparent quote.`,
    },
    {
      q: `Which modular kitchen layout is best for homes in ${localityName}?`,
      a: `The best layout depends on your kitchen shape. L-Shape suits corner kitchens in ${localityName} apartments and villas. Parallel works well in narrow galley kitchens. Straight is ideal for compact studios. U-Shape maximises storage in large kitchens. Our designer will recommend the right layout after a free site visit.`,
    },
    {
      q: `Do you install modular kitchens in ${localityName}, ${cityName}?`,
      a: `Yes — FurniRevive serves ${localityName} and the wider ${cityName} region. Our local team handles everything: site measurement, 3D design, factory manufacturing, delivery, and installation. Most kitchens are ready within 2–4 weeks from design approval.`,
    },
    {
      q: `What warranty do FurniRevive kitchens come with in ${localityName}?`,
      a: `All FurniRevive modular kitchens in ${localityName} carry a 10-year structural warranty on the carcass and hardware, plus a 5-year finish warranty on shutters and surfaces. We also provide 6 months of free post-installation support.`,
    },
  ] as const;
}

// ─── Price helper (same multipliers as layout-locality registry) ─────────────
const CITY_MULT: Record<string, number> = {
  delhi: 1.1, gurgaon: 1.25, noida: 1.0, faridabad: 0.88, ghaziabad: 0.85,
  chandigarh: 0.95, mohali: 0.90, panchkula: 0.92,
};
const AFF_MIN: Record<string, number> = { "ultra-high": 2.2, "high": 1.8, "mid-high": 1.4, "mid": 1.1 };
const AFF_MAX: Record<string, number> = { "ultra-high": 4.5, "high": 3.5, "mid-high": 2.8, "mid": 2.2 };
const BASE = 160000; // parallel base — representative for hub
function rnd(n: number) { return Math.round(n / 10000) * 10000; }

function hubPrice(city: string, aff: string) {
  const cm = CITY_MULT[city] ?? 1.0;
  return { min: rnd(BASE * cm * AFF_MIN[aff]), max: rnd(BASE * cm * AFF_MAX[aff]) };
}

