function makeHub(r: Raw): KitchenLocalityHubEntry {
  const { min, max } = hubPrice(r.city, r.aff);
  return {
    urlSlug: `modular-kitchen-${r.slug}`,
    localitySlug: r.slug,
    localityName: r.name,
    citySlug: r.city,
    cityName: r.cityName,
    affluence: r.aff,
    priceMin: min,
    priceMax: max,
    nearby: r.nearby,
  };
}

export const KITCHEN_LOCALITY_HUB_REGISTRY: readonly KitchenLocalityHubEntry[] =
  [...RAW_NCR, ...RAW_TRICITY].map(makeHub);

export function getLocalityHubEntry(urlSlug: string): KitchenLocalityHubEntry | undefined {
  return KITCHEN_LOCALITY_HUB_REGISTRY.find((e) => e.urlSlug === urlSlug);
}

/** All layout×locality pages for a given locality slug */
export function getLayoutsForLocality(localitySlug: string) {
  return KITCHEN_LAYOUT_LOCALITY_REGISTRY.filter((e) => e.slug === localitySlug);
}
